@startuml

class Library {
}

class User {
  + SecurityDeposit : float
  + ContactInfo : string
}

class BorrowableItem {
  + LibraryCode : string
  + Location : string
}

class Book {
  + Publisher : string
}

class MagazineIssue {
  + PublicationDate : date
  + Publisher : string
}

class MusicCD {
  + Publisher : string
  + Artist : string
}

class Film {
  + Duration : int
  + Publisher : string
}

class Author {
  + Name : string
}

class Actor {
  + Name : string
}

class BookAuthor {
}

class FilmActor {
}

class Loan {
  + ReturnDeadline : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
BorrowableItem "0..1" -- "0..1" User : lent to
BorrowableItem "1" -- "0..1" Loan : associated with
User "1" -- "0..3" Loan : makes

Book "1" -- "*" BookAuthor : has
BookAuthor "*" -- "1" Book : written by
Book "1" -- "1" Author : has
MagazineIssue "1" -- "1" Library : belongs to

MusicCD "1" -- "1" Artist : has
Film "1" -- "*" FilmActor : has
FilmActor "*" -- "1" Actor : acts in

Book extends BorrowableItem {}
MagazineIssue extends BorrowableItem {}
MusicCD extends BorrowableItem {}
Film extends BorrowableItem {}

class DVDFilm extends Film {}
class VHSFilm extends Film {}

@enduml

